CREATE TABLE public.digest_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, ticker text NOT NULL, period_end text NOT NULL, accession text NOT NULL, recipient text NOT NULL, status text NOT NULL CHECK (status IN ('sending','sent','failed','uncertain')), gmail_id text, error text, created_at timestamptz NOT NULL DEFAULT now(), sent_at timestamptz, UNIQUE(user_id,ticker,period_end)); GRANT SELECT ON public.digest_deliveries TO authenticated; GRANT ALL ON public.digest_deliveries TO service_role; ALTER TABLE public.digest_deliveries ENABLE ROW LEVEL SECURITY; CREATE POLICY "Owners read digest delivery history" ON public.digest_deliveries FOR SELECT TO authenticated USING (auth.uid() = user_id);